const desc = e => { let s=e.tagName.toLowerCase(); if(e.id) s+='#'+e.id; if(e.className && typeof e.className==='string') s+='.'+e.className.trim().split(/\s+/).join('.'); return s; };
out.focusables = [...document.querySelectorAll('a[href],button,input,select,textarea,[tabindex]')].slice(0,60).map(e=>desc(e)+' |ti='+e.getAttribute('tabindex')+'|al='+e.getAttribute('aria-label')+'|title='+e.getAttribute('title')+'|txt='+e.textContent.trim().slice(0,30)+'|dis='+e.disabled+'|type='+e.type);
return out;
}"}

{"function":"() => {
const tags = new Set();
const shadows = [];
document.querySelectorAll('*').forEach(e=>{ if(e.tagName.includes('-')) tags.add(e.tagName.toLowerCase()); if(e.shadowRoot) shadows.push(e.tagName.toLowerCase()+(e.id?'#'+e.id:'')+'.'+e.className); });
return {tags:[...tags], shadows: shadows.slice(0,80), nShadow: shadows.length};
}"}

{"function":"() => {
const row = document.querySelector('tbody tr');
const ser = (e, d=0) => { if(d>6) return ''; let s = '  '.repeat(d)+'<'+e.tagName.toLowerCase()+[...e.attributes].filter(a=>!a.name.startsWith('_ng')).map(a=>' '+a.name+'="'+a.value.slice(0,60)+'"').join('')+'>' + ([...e.childNodes].filter(n=>n.nodeType==3 && n.textContent.trim()).map(n=>n.textContent.trim()).join(' ')) + '\n'; for(const c of e.children) s+=ser(c,d+1); if(e.shadowRoot){ s+='  '.repeat(d+1)+'#shadow\n'; for(const c of e.shadowRoot.children) if(c.tagName!='STYLE') s+=ser(c,d+2);} return s; };
return ser(row.lastElementChild) + '\n----\n' + ser(document.querySelector('pnip-filter-panel'));
}"}

{"function":"() => {
const ser = (e, d=0) => { if(d>9) return ''; let s = '  '.repeat(d)+'<'+e.tagName.toLowerCase()+[...e.attributes].filter(a=>!a.name.startsWith('_ng')).map(a=>' '+a.name+'="'+a.value.slice(0,70)+'"').join('')+'>' + ([...e.childNodes].filter(n=>n.nodeType==3 && n.textContent.trim()).map(n=>n.textContent.trim()).join(' ')) + '\n'; for(const c of e.children) if(!['STYLE','SCRIPT'].includes(c.tagName)) s+=ser(c,d+1); if(e.shadowRoot){ s+='  '.repeat(d+1)+'#shadow\n'; for(const c of e.shadowRoot.children) if(!['STYLE','LINK'].includes(c.tagName)) s+=ser(c,d+2);} return s; };
const th = document.querySelectorAll('thead th');
return ser(th[1]) + ser(document.querySelector('tbody tr td:nth-child(2)')) + '\n---\n' + ser(document.querySelector('pnip-search-table-utils')).slice(0,4000);
