{"function":"() => {
const parse = c => c.match(/[\d.]+/g).map(Number);
const lum = ([r,g,b]) => { const f=v=>{v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4)}; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const bgOf = e => { while(e){ const c=getComputedStyle(e).backgroundColor; const p=parse(c); if(p.length<4 || p[3]>0) return c; e=e.parentElement || (e.getRootNode().host); } return 'rgb(255,255,255)'; };
const cr = (a,b)=>{const l1=lum(parse(a)),l2=lum(parse(b)); return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)};
const check = sel => { const e=document.querySelector(sel); if(!e) return sel+': none'; const cs=getComputedStyle(e); const bg=bgOf(e); return sel+' | '+cs.color+' on '+bg+' = '+cr(cs.color,bg)+' | '+cs.fontSize+' '+cs.fontWeight+' | "'+e.textContent.trim().slice(0,30)+'"'; };
return ['pnip-status-solicitacao-utils .text-secondary-01','pnip-filter-panel span.br-tag span.text-gray-50','pnip-filter-panel span.br-tag i','.br-tag.primary-pastel-01','thead th','tbody td','.br-breadcrumb .crumb span','.tab-nav button','.tab-nav .tab-item.active button','pnip-filter-panel button.br-button.secondary','.br-pagination .page','.br-sign-in'].map(check);
}"}

